 Append(~weights,w);Append(~records,[*i,vt,w,square*]);end for;assert #infty eq 4 and Sort(weights) eq [1,1,2,2,6,6,6,6];base:=Divisor(cs[[i:i in [1..#cs]|weights[i] eq 1][1]]);ivs:=ClassGroupAbelianInvariants(F:ReductionDivisor:=base,Proof:=true);assert F`cld`proven;MDProvenClassGroupGenerators(F);G:=F`cld`Cl;
